import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function ProviderDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [earnings, setEarnings] = useState({ totalRevenue: 0, totalEarnings: 0, platformFees: 0, totalBookings: 0 });
  const [pendingPayout, setPendingPayout] = useState(0);
  const [payoutHistory, setPayoutHistory] = useState([]);
  const [pendingPayoutAmount, setPendingPayoutAmount] = useState(0);
  const [pendingPayoutCount, setPendingPayoutCount] = useState(0);
  const [recentPayments, setRecentPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingPayouts, setLoadingPayouts] = useState(false);
  const [showPayoutModal, setShowPayoutModal] = useState(false);
  const [showServiceModal, setShowServiceModal] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [payoutAmount, setPayoutAmount] = useState('');

  const [serviceForm, setServiceForm] = useState({
    name: '', description: '', category: 'oil-change', price: '', duration: '30',
    discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: ''
  });

  const categories = [
    { id: 'oil-change', name: 'Oil Change', icon: '🛢️' },
    { id: 'brake-repair', name: 'Brake Repair', icon: '🛑' },
    { id: 'tire-service', name: 'Tire Service', icon: '🛞' },
    { id: 'engine-repair', name: 'Engine Repair', icon: '🔧' },
    { id: 'ac-repair', name: 'AC Repair', icon: '❄️' },
    { id: 'transmission', name: 'Transmission', icon: '⚙️' },
    { id: 'detailing', name: 'Detailing', icon: '🧼' },
    { id: 'maintenance', name: 'Maintenance', icon: '📋' },
    { id: 'electrical', name: 'Electrical', icon: '⚡' },
    { id: 'body-repair', name: 'Body Repair', icon: '🚘' }
  ];

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchServices(),
        fetchBookings(),
        fetchEarnings(),
        fetchPayoutHistory()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    const res = await fetch('http://localhost:5000/api/services/provider/my-services', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setServices(data.services);
  };

  const fetchBookings = async () => {
    const res = await fetch('http://localhost:5000/api/services/provider/bookings', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setBookings(data.bookings);
  };

  const fetchEarnings = async () => {
    const res = await fetch('http://localhost:5000/api/payments/provider/earnings', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) {
      setEarnings(data.earnings);
      setPendingPayout(data.pendingPayout || 0);
      setRecentPayments(data.recentPayments || []);
    }
  };

  const fetchPayoutHistory = async () => {
    setLoadingPayouts(true);
    try {
      const res = await fetch('http://localhost:5000/api/payments/provider/payout-history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        setPayoutHistory(data.payoutHistory || []);
        setPendingPayoutAmount(data.pendingAmount || 0);
        setPendingPayoutCount(data.pendingCount || 0);
      }
    } catch (error) {
      console.error('Error fetching payout history:', error);
    } finally {
      setLoadingPayouts(false);
    }
  };

  const handleServiceSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        ...serviceForm,
        price: parseFloat(serviceForm.price),
        duration: parseInt(serviceForm.duration),
        discountedPrice: serviceForm.discountedPrice ? parseFloat(serviceForm.discountedPrice) : undefined,
        tags: serviceForm.tags.split(',').map(t => t.trim()),
        requirements: serviceForm.requirements.split(',').map(r => r.trim()),
        inclusions: serviceForm.inclusions.split(',').map(i => i.trim())
      };

      let url = 'http://localhost:5000/api/services';
      let method = 'POST';

      if (editingService) {
        url = `http://localhost:5000/api/services/${editingService._id}`;
        method = 'PUT';
      }

      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        toast.success(editingService ? 'Service updated!' : 'Service added!');
        setShowServiceModal(false);
        setEditingService(null);
        setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' });
        fetchServices();
      }
    } catch (error) {
      toast.error('Failed to save service');
    }
  };

  const handleDeleteService = async (serviceId) => {
    if (window.confirm('Are you sure you want to delete this service?')) {
      try {
        const res = await fetch(`http://localhost:5000/api/services/${serviceId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Service deleted!');
          fetchServices();
        }
      } catch (error) {
        toast.error('Failed to delete service');
      }
    }
  };

  const handleToggleStatus = async (serviceId, currentStatus) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/${serviceId}/toggle-status`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Service ${data.service.isActive ? 'activated' : 'deactivated'}`);
        fetchServices();
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const updateBookingStatus = async (bookingId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/provider/bookings/${bookingId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Booking ${status}!`);
        fetchBookings();
      }
    } catch (error) {
      toast.error('Failed to update booking');
    }
  };

  const editService = (service) => {
    setEditingService(service);
    setServiceForm({
      name: service.name,
      description: service.description,
      category: service.category,
      price: service.price,
      duration: service.duration,
      discountedPrice: service.discountedPrice || '',
      warranty: service.warranty || '',
      tags: (service.tags || []).join(', '),
      requirements: (service.requirements || []).join(', '),
      inclusions: (service.inclusions || []).join(', ')
    });
    setShowServiceModal(true);
  };

  const requestPayout = async () => {
    if (!payoutAmount || parseFloat(payoutAmount) <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (parseFloat(payoutAmount) > pendingPayoutAmount) {
      toast.error('Amount exceeds available balance');
      return;
    }

    try {
      const res = await fetch('http://localhost:5000/api/payments/provider/payout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ amount: parseFloat(payoutAmount) })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Payout request submitted!');
        setShowPayoutModal(false);
        setPayoutAmount('');
        fetchEarnings();
        fetchPayoutHistory();
      } else {
        toast.error(data.error);
      }
    } catch (error) {
      toast.error('Failed to request payout');
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const totalRevenue = earnings.totalRevenue || 0;
  const yourEarnings = earnings.totalEarnings || 0;
  const platformFees = earnings.platformFees || 0;
  const completedBookings = earnings.totalBookings || 0;
  const pendingBookings = bookings.filter(b => b.status === 'pending').length;

  return (
    <div style={styles.dashboard}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🔧</span>
          <h1 style={styles.logoText}>Car Care Connect - Provider</h1>
        </div>
        <div style={styles.userInfo}>
          <span>🔧 {user?.businessName || user?.firstName}</span>
          <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
        </div>
      </div>

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}><h3>💰 Total Revenue</h3><p style={styles.statNumber}>${totalRevenue.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>💵 Your Earnings</h3><p style={styles.statNumber}>${yourEarnings.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>📊 Platform Fee</h3><p style={styles.statNumber}>${platformFees.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>📅 Completed</h3><p style={styles.statNumber}>{completedBookings}</p></div>
        <div style={styles.statCard}><h3>⏳ Pending</h3><p style={styles.statNumber}>{pendingBookings}</p></div>
        <div style={styles.statCard}><h3>💰 Pending Payout</h3><p style={styles.statNumber}>${pendingPayoutAmount.toLocaleString()}</p><button style={styles.payoutBtn} onClick={() => setShowPayoutModal(true)}>Request</button></div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => setActiveTab('services')}>🛠️ Services</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings</button>
        <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>💰 Earnings</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div style={styles.twoColumn}>
                <div>
                  <div style={styles.card}>
                    <h3>📈 Recent Activity</h3>
                    {bookings.slice(0, 5).map(booking => (
                      <div key={booking._id} style={styles.activityItem}>
                        <span>{booking.serviceName} - {booking.customerId?.firstName}</span>
                        <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      </div>
                    ))}
                  </div>
                </div>
                <div>
                  <div style={styles.card}>
                    <h3>💰 Recent Payments</h3>
                    {recentPayments.map(payment => (
                      <div key={payment._id} style={styles.paymentItem}>
                        <span>{payment.bookingId?.serviceName}</span>
                        <span>${payment.amount}</span>
                        <span style={{ color: '#10b981' }}>+${payment.providerEarnings}</span>
                      </div>
                    ))}
                  </div>
                  <div style={styles.card}>
                    <h3>📦 Quick Actions</h3>
                    <button style={styles.actionBtn} onClick={() => setActiveTab('services')}>➕ Add Service</button>
                    <button style={styles.actionBtn} onClick={() => setActiveTab('bookings')}>📅 View Bookings</button>
                  </div>
                </div>
              </div>
            )}

            {/* Services Tab */}
            {activeTab === 'services' && (
              <div>
                <button style={styles.addBtn} onClick={() => { setEditingService(null); setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' }); setShowServiceModal(true); }}>+ Add Service</button>
                <div style={styles.servicesGrid}>
                  {services.length === 0 ? (
                    <div style={styles.emptyState}>No services added yet. Click "Add Service" to get started!</div>
                  ) : (
                    services.map(service => {
                      const serviceBookings = bookings.filter(b => b.serviceId === service._id);
                      const serviceRevenue = serviceBookings.filter(b => b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0);
                      return (
                        <div key={service._id} style={styles.serviceCard}>
                          <div style={styles.serviceHeader}>
                            <h3>{service.name}</h3>
                            <span style={{ backgroundColor: service.isActive ? '#d1fae5' : '#fee2e2', color: service.isActive ? '#065f46' : '#991b1b', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>
                              {service.isActive ? 'Active' : 'Inactive'}
                            </span>
                          </div>
                          <p style={styles.serviceDesc}>{service.description?.substring(0, 80)}...</p>
                          <div style={styles.serviceDetails}>
                            <span>{categories.find(c => c.id === service.category)?.icon} {service.category}</span>
                            <span>💰 ${service.price}</span>
                            <span>⏱️ {service.duration} min</span>
                          </div>
                          <div style={styles.serviceStats}>
                            <span>📊 {serviceBookings.length} bookings</span>
                            <span>💰 ${serviceRevenue} revenue</span>
                          </div>
                          <div style={styles.serviceActions}>
                            <button style={styles.editBtn} onClick={() => editService(service)}>✏️ Edit</button>
                            <button style={styles.toggleBtn} onClick={() => handleToggleStatus(service._id, service.isActive)}>{service.isActive ? '🔴 Deactivate' : '🟢 Activate'}</button>
                            <button style={styles.deleteBtn} onClick={() => handleDeleteService(service._id)}>🗑️ Delete</button>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>
              </div>
            )}

            {/* Bookings Tab */}
            {activeTab === 'bookings' && (
              <div>
                {bookings.length === 0 ? (
                  <div style={styles.emptyState}>No bookings yet.</div>
                ) : (
                  bookings.map(booking => (
                    <div key={booking._id} style={styles.bookingCard}>
                      <div style={styles.bookingHeader}>
                        <div>
                          <h3>{booking.serviceName}</h3>
                          <p><strong>Customer:</strong> {booking.customerId?.firstName} {booking.customerId?.lastName}</p>
                          <p><strong>Phone:</strong> {booking.customerId?.phone}</p>
                        </div>
                        <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      </div>
                      <div style={styles.bookingDetails}>
                        <span>📅 {new Date(booking.bookingDate).toLocaleDateString()}</span>
                        <span>⏰ {booking.bookingTime}</span>
                        <span>💰 ${booking.totalAmount}</span>
                        {booking.isConcierge && <span>🚗 Concierge - Pickup: {booking.pickupAddress}</span>}
                      </div>
                      {booking.status === 'pending' && (
                        <div style={styles.bookingActions}>
                          <button style={styles.confirmBtn} onClick={() => updateBookingStatus(booking._id, 'confirmed')}>✓ Confirm</button>
                          <button style={styles.rejectBtn} onClick={() => updateBookingStatus(booking._id, 'cancelled')}>✗ Reject</button>
                        </div>
                      )}
                      {booking.status === 'confirmed' && (
                        <button style={styles.startBtn} onClick={() => updateBookingStatus(booking._id, 'in-progress')}>▶ Start Service</button>
                      )}
                      {booking.status === 'in-progress' && (
                        <button style={styles.completeBtn} onClick={() => updateBookingStatus(booking._id, 'completed')}>✅ Complete</button>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Earnings Tab */}
            {activeTab === 'earnings' && (
              <div>
                <div style={styles.earningsSummary}>
                  <h2>💰 Earnings & Payouts</h2>
                  <div style={styles.earningsGrid}>
                    <div style={styles.earningsCard}><h3>Total Revenue</h3><p>${totalRevenue.toLocaleString()}</p><small>From {completedBookings} bookings</small></div>
                    <div style={styles.earningsCard}><h3>Your Earnings</h3><p style={{ color: '#10b981' }}>${yourEarnings.toLocaleString()}</p><small>70% of revenue</small></div>
                    <div style={styles.earningsCard}><h3>Platform Fee</h3><p style={{ color: '#f59e0b' }}>${platformFees.toLocaleString()}</p><small>15% commission</small></div>
                  </div>
                </div>

                {/* Pending Payout Section */}
                <div style={styles.pendingSection}>
                  <h3>💸 Pending Payout</h3>
                  <div style={styles.pendingCard}>
                    <div>
                      <span style={styles.pendingAmount}>${pendingPayoutAmount.toLocaleString()}</span>
                      <span>pending for {pendingPayoutCount} booking{pendingPayoutCount !== 1 ? 's' : ''}</span>
                    </div>
                    <button style={styles.payoutBtnLarge} onClick={() => setShowPayoutModal(true)}>Request Payout</button>
                  </div>
                </div>

                {/* Payout History Section */}
                <div style={styles.card}>
                  <h3>📋 Payout History</h3>
                  {loadingPayouts ? (
                    <div style={styles.loading}>Loading payout history...</div>
                  ) : payoutHistory.length === 0 ? (
                    <div style={styles.emptyState}>No payout history yet. Request your first payout!</div>
                  ) : (
                    <div style={styles.payoutList}>
                      {payoutHistory.map(payout => (
                        <div key={payout._id} style={styles.payoutItem}>
                          <div>
                            <strong>{payout._id}</strong>
                            <div style={styles.payoutDate}>{new Date(payout.date).toLocaleDateString()}</div>
                          </div>
                          <div>
                            <span style={styles.payoutAmount}>${payout.amount.toLocaleString()}</span>
                            <div style={styles.payoutCount}>{payout.count} booking{payout.count !== 1 ? 's' : ''}</div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div style={styles.card}>
                  <h3>📋 Recent Transactions</h3>
                  {recentPayments.map(payment => (
                    <div key={payment._id} style={styles.transactionItem}>
                      <div><strong>{payment.bookingId?.serviceName}</strong><div>{new Date(payment.createdAt).toLocaleDateString()}</div></div>
                      <div>Customer paid: ${payment.amount}</div>
                      <div>You earned: <strong style={{ color: '#10b981' }}>+${payment.providerEarnings}</strong></div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Service Modal */}
      {showServiceModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>{editingService ? 'Edit Service' : 'Add New Service'}</h2>
            <form onSubmit={handleServiceSubmit}>
              <input style={styles.input} placeholder="Service Name" value={serviceForm.name} onChange={(e) => setServiceForm({...serviceForm, name: e.target.value})} required />
              <textarea style={styles.textarea} placeholder="Description" value={serviceForm.description} onChange={(e) => setServiceForm({...serviceForm, description: e.target.value})} required />
              <select style={styles.input} value={serviceForm.category} onChange={(e) => setServiceForm({...serviceForm, category: e.target.value})}>
                {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.icon} {cat.name}</option>)}
              </select>
              <div style={styles.row}>
                <input style={styles.inputHalf} type="number" placeholder="Price ($)" value={serviceForm.price} onChange={(e) => setServiceForm({...serviceForm, price: e.target.value})} required />
                <input style={styles.inputHalf} type="number" placeholder="Discounted Price" value={serviceForm.discountedPrice} onChange={(e) => setServiceForm({...serviceForm, discountedPrice: e.target.value})} />
              </div>
              <div style={styles.row}>
                <input style={styles.inputHalf} type="number" placeholder="Duration (minutes)" value={serviceForm.duration} onChange={(e) => setServiceForm({...serviceForm, duration: e.target.value})} required />
                <input style={styles.inputHalf} placeholder="Warranty" value={serviceForm.warranty} onChange={(e) => setServiceForm({...serviceForm, warranty: e.target.value})} />
              </div>
              <input style={styles.input} placeholder="Tags (comma separated)" value={serviceForm.tags} onChange={(e) => setServiceForm({...serviceForm, tags: e.target.value})} />
              <textarea style={styles.textarea} placeholder="Requirements (comma separated)" value={serviceForm.requirements} onChange={(e) => setServiceForm({...serviceForm, requirements: e.target.value})} />
              <textarea style={styles.textarea} placeholder="Inclusions (comma separated)" value={serviceForm.inclusions} onChange={(e) => setServiceForm({...serviceForm, inclusions: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save</button>
                <button type="button" style={styles.cancelBtn} onClick={() => { setShowServiceModal(false); setEditingService(null); }}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Payout Modal */}
      {showPayoutModal && (
        <div style={styles.modal}>
          <div style={styles.modalContentSmall}>
            <h2>💰 Request Payout</h2>
            <p>Available for payout: <strong>${pendingPayoutAmount.toLocaleString()}</strong></p>
            <input style={styles.input} type="number" placeholder="Amount" value={payoutAmount} onChange={(e) => setPayoutAmount(e.target.value)} />
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={requestPayout}>Request Payout</button>
              <button style={styles.cancelBtn} onClick={() => { setShowPayoutModal(false); setPayoutAmount(''); }}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

