  userInfo: { display: 'flex', gap: '15px', alignItems: 'center' }, logoutButton: { backgroundColor: 'transparent', border: '1px solid white', color: 'white', padding: '6px 15px', borderRadius: '6px', cursor: 'pointer' },
  statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: '15px', padding: '20px 30px' },
