  tab: { padding: '12px 24px', background: 'none', border: 'none', cursor: 'pointer', fontSize: '14px', fontWeight: '500' },
  activeTab: { borderBottom: '2px solid #10b981', color: '#10b981' },
  content: { padding: '30px', maxWidth: '1400px', margin: '0 auto' }, loading: { textAlign: 'center', padding: '50px' },
  twoColumn: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' },
